import struct
import gobject

class FileTransferSession(gobject.GObject):
    __gsignals__ = {
        'transfer-progress': (gobject.SIGNAL_RUN_FIRST, gobject.TYPE_NONE, (gobject.TYPE_FLOAT,)),
        'transfer-completed': (gobject.SIGNAL_RUN_FIRST, gobject.TYPE_NONE, ()),
        'transfer-failed': (gobject.SIGNAL_RUN_FIRST, gobject.TYPE_NONE, (gobject.TYPE_STRING,))
    }

    def __init__(self, peer, filename, filesize):
        gobject.GObject.__init__(self)
        self._peer = peer
        self._filename = filename
        self._size = filesize
        self._data = None
        self._has_preview = False
        self._preview = None
        self._state = 'initial'
        self._transferred_bytes = 0
        self._chunk_size = 4096

    def invite(self):
        """Initiate file transfer invitation"""
        if self._state != 'initial':
            raise ValueError("Invalid transfer state")

        context = self._build_context()
        try:
            self._peer.send_file_invitation(context)
            self._state = 'invited'
        except Exception as e:
            self.emit('transfer-failed', str(e))

    def accept(self):
        """Accept incoming file transfer"""
        if self._state != 'pending':
            raise ValueError("Cannot accept transfer")

        try:
            self._peer.accept_file_transfer()
            self._state = 'accepted'
        except Exception as e:
            self.emit('transfer-failed', str(e))

    def reject(self):
        """Reject incoming file transfer"""
        if self._state != 'pending':
            raise ValueError("Cannot reject transfer")

        try:
            self._peer.reject_file_transfer()
            self._state = 'rejected'
        except Exception as e:
            self.emit('transfer-failed', str(e))

    def cancel(self):
        """Cancel ongoing file transfer"""
        if self._state not in ['accepted', 'transferring']:
            raise ValueError("Cannot cancel transfer")

        try:
            self._peer.cancel_file_transfer()
            self._state = 'cancelled'
        except Exception as e:
            self.emit('transfer-failed', str(e))

    def send(self, data):
        """Send file data"""
        if self._state != 'accepted':
            raise ValueError("Cannot send data")

        try:
            for i in range(0, len(data), self._chunk_size):
                chunk = data[i:i+self._chunk_size]
                self._peer.send_file_chunk(chunk)
                self._transferred_bytes += len(chunk)
                progress = (self._transferred_bytes / self._size) * 100
                self.emit('transfer-progress', progress)

            self._state = 'completed'
            self.emit('transfer-completed')
        except Exception as e:
            self.emit('transfer-failed', str(e))

    def _build_context(self):
        """Build file transfer context"""
        context = {
            'filename': self._filename,
            'filesize': self._size,
            'preview': self._preview if self._has_preview else None
        }

        return struct.pack('>I', len(str(context))) + str(context).encode('utf-8')

    def parse_context(self, context_data):
        """Parse incoming file transfer context"""
        try:
            context_length = struct.unpack('>I', context_data[:4])[0]
            context_str = context_data[4:4+context_length].decode('utf-8')
            context = eval(context_str)

            self._filename = context.get('filename', '')
            self._size = context.get('filesize', 0)

            if context.get('preview'):
                self._has_preview = True
                self._preview = context['preview']

            self._state = 'pending'
            return context
        except Exception as e:
            self.emit('transfer-failed', str(e))
            return None

    def get_filename(self):
        """Get filename"""
        return self._filename

    def get_filesize(self):
        """Get file size"""
        return self._size

    def has_preview(self):
        """Check if preview exists"""
        return self._has_preview

    def get_preview(self):
        """Get file preview"""
        return self._preview if self._has_preview else None

    def get_state(self):
        """Get current transfer state"""
        return self._state

from flask import Blueprint, render_template, request, redirect, url_for, flash
from sqlalchemy.exc import SQLAlchemyError
from marshmallow import ValidationError
from app.models import Project
from app.schemas import ProjectSchema
from app import db

projects = Blueprint('projects', __name__, url_prefix='/projects')

def get_project_or_404(project_id):
    """Retrieve a project by ID or return 404."""
    project = Project.query.get_or_404(project_id)
    return project

@projects.route('/', methods=['GET'])
def projects_index():
    """List all projects."""
    try:
        projects_list = Project.query.all()
        return render_template('projects/index.html', projects=projects_list)
    except SQLAlchemyError as e:
        flash(f'Error retrieving projects: {str(e)}', 'error')
        return redirect(url_for('main.index'))

@projects.route('/add', methods=['GET', 'POST'])
def projects_add():
    """Add a new project."""
    if request.method == 'POST':
        try:
            schema = ProjectSchema()
            project_data = schema.load(request.form)

            new_project = Project(**project_data)
            db.session.add(new_project)
            db.session.commit()

            flash('Project successfully added!', 'success')
            return redirect(url_for('projects.projects_index'))

        except ValidationError as validation_err:
            flash(f'Validation Error: {validation_err.messages}', 'error')
        except SQLAlchemyError as db_err:
            db.session.rollback()
            flash(f'Database Error: {str(db_err)}', 'error')

    return render_template('projects/add.html')

@projects.route('/update/<int:project_id>', methods=['GET', 'POST'])
def projects_update(project_id):
    """Update an existing project."""
    project = get_project_or_404(project_id)

    if request.method == 'POST':
        try:
            schema = ProjectSchema(partial=True)
            project_data = schema.load(request.form)

            for key, value in project_data.items():
                setattr(project, key, value)

            db.session.commit()
            flash('Project successfully updated!', 'success')
            return redirect(url_for('projects.projects_index'))

        except ValidationError as validation_err:
            flash(f'Validation Error: {validation_err.messages}', 'error')
        except SQLAlchemyError as db_err:
            db.session.rollback()
            flash(f'Database Error: {str(db_err)}', 'error')

    return render_template('projects/update.html', project=project)

@projects.route('/delete/<int:project_id>', methods=['POST'])
def projects_delete(project_id):
    """Delete a project."""
    project = get_project_or_404(project_id)

    try:
        db.session.delete(project)
        db.session.commit()
        flash('Project successfully deleted!', 'success')
    except SQLAlchemyError as e:
        db.session.rollback()
        flash(f'Error deleting project: {str(e)}', 'error')

    return redirect(url_for('projects.projects_index'))

