from openerp.tools.safe_eval import safe_eval

class Env(dict):
    def __init__(self, cr, uid, pool, context=None):
        super(Env, self).__init__()
        self.cr = cr
        self.uid = uid
        self.pool = pool
        self.context = context or {}

    def __getattr__(self, name):
        try:
            return self[name]
        except KeyError:
            raise AttributeError(name)

class WorkflowManager:
    def __init__(self, pool, cr, uid, context=None):
        self.pool = pool
        self.cr = cr
        self.uid = uid
        self.context = context or {}

    def _eval_expr(self, expr, workitem):
        try:
            env = Env(self.cr, self.uid, self.pool, self.context)
            env.update({
                'object': workitem.object,
                'workitem': workitem,
                'cr': self.cr,
                'uid': self.uid,
                'pool': self.pool
            })
            return safe_eval(expr, env)
        except Exception as e:
            return False

    def execute_action(self, activity, workitem):
        action_type = activity.action_type
        if action_type == 'server':
            try:
                model = self.pool.get(workitem.model)
                method = getattr(model, activity.action_method)
                return method(self.cr, self.uid, [workitem.res_id], self.context)
            except Exception as e:
                return False
        return False

    def check_transition_condition(self, transition, workitem):
        if not transition.condition:
            return True
        return self._eval_expr(transition.condition, workitem)

    def check_user_permissions(self, activity, workitem):
        user_obj = self.pool.get('res.users')
        user_groups = user_obj.browse(self.cr, self.uid, self.uid).groups_id

        required_groups = activity.required_groups
        for group in required_groups:
            if group not in user_groups:
                return False
        return True

    def execute(self, workitem):
        current_activity = workitem.current_activity

        if not self.check_user_permissions(current_activity, workitem):
            return False

        if current_activity.action_type:
            action_result = self.execute_action(current_activity, workitem)
            if not action_result:
                return False

        valid_transitions = [
            transition for transition in current_activity.outgoing_transitions
            if self.check_transition_condition(transition, workitem)
        ]

        if not valid_transitions:
            return False

        next_transition = valid_transitions[0]
        workitem.current_activity = next_transition.target_activity
        return True

    def handle_workflow_signal(self, model, res_id, signal):
        workitem = self.find_workitem(model, res_id)
        if workitem and signal in workitem.available_signals:
            return self.execute(workitem)
        return False

    def find_workitem(self, model, res_id):
