import os
import shutil
import glob
import re

class PGLDDLDeployTestAutomation:
    def __init__(self, base_dir, postgres_version):
        self.base_dir = base_dir
        self.postgres_version = postgres_version
        self.files = {}
        self.max_file_num = 0
        self.NEW_FILES = ['pre_test', 'post_test', 'sql', 'expected']

    def clean_existing_test_files(self, pattern='test_*'):
        """Remove existing test files matching specified pattern"""
        for file_type in self.NEW_FILES:
            matching_files = glob.glob(os.path.join(self.base_dir, f'{pattern}.{file_type}'))
            for file_path in matching_files:
                try:
                    os.remove(file_path)
                except OSError as e:
                    print(f"Error removing {file_path}: {e}")

    def construct_filename(self, file_type):
        """Generate incrementally numbered test filenames"""
        self.max_file_num += 1
        return os.path.join(
            self.base_dir, 
            f'test_{self.max_file_num:03d}.{file_type}'
        )

    def generate_sql_contents(self):
        """Generate SQL script template with dynamic configuration"""
        contents = f"""
-- Test scenario for pgl_ddl_deploy extension
-- PostgreSQL Version: {self.postgres_version}

-- Setup extension
CREATE EXTENSION IF NOT EXISTS pgl_ddl_deploy VERSION '{self.postgres_version}';

-- Dynamic table creation
CREATE TABLE test_schema.dynamic_table (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100),
    created_at TIMESTAMP DEFAULT NOW()
);

-- Extension-specific configuration
SELECT pgl_ddl_deploy.override(
    'test_schema',
    'dynamic_table',
    'ADD COLUMN version_info TEXT'
);

-- Subscription refresh mechanism
SELECT pgl_ddl_deploy.notify_subscription_refresh();

-- Error retry configuration
SELECT pgl_ddl_deploy.retry_all_subscriber_logs();

-- Complex schema evolution scenario
ALTER TABLE test_schema.dynamic_table 
    ADD COLUMN modified_at TIMESTAMP,
    ADD COLUMN status VARCHAR(50) DEFAULT 'active';

-- Validate extension behavior
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name = 'dynamic_table' 
        AND column_name = 'status'
    ) THEN
        RAISE EXCEPTION 'Schema evolution failed';
    END IF;
END $$;
"""
        return contents

    def create_test_files(self):
        """Generate comprehensive test files for different scenarios"""
        self.files = {
            file_type: self.construct_filename(file_type)
            for file_type in self.NEW_FILES
        }

        # Write SQL contents
        with open(self.files['sql'], 'w') as f:
            f.write(self.generate_sql_contents())

        # Create placeholder files for other test components
        for file_type in ['pre_test', 'post_test', 'expected']:
            with open(self.files[file_type], 'w') as f:
                f.write(f'-- {file_type.replace("_", " ").title()} Placeholder')

    def validate_test_files(self):
        """Validate generated test files"""
        for file_type, file_path in self.files.items():
            if not os.path.exists(file_path):
                print(f"Warning: {file_type} file not created")
            else:
                file_size = os.path.getsize(file_path)
                print(f"{file_type} file created: {file_path} ({file_size} bytes)")

    def run_test_generation(self):
        """Orchestrate entire test file generation process"""
        try:
            self.clean_existing_test_files()
            self.create_test_files()
            self.validate_test_files()
        except Exception as e:
            print(f"Test generation failed: {e}")

def main():
    # Example usage
    base_directory = '/path/to/test/directory'
    postgres_version = '13.4'

    test_automation = PGLDDLDeployTestAutomation(base_directory, postgres_version)
    test_automation.run_test_generation()

if __name__ == '__main__':
    main()

import scrapelib
import logging
from pupa.scrape import Person, Scraper
from openstates.utils import validate_phone_number, validate_email
import json
import requests

class UTPersonScraper(Scraper):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.session = scrapelib.Scraper(requests_per_minute=10)
        self.logger = logging.getLogger(self.__class__.__name__)

    PARTIES = {
        'R': 'Republican',
        'D': 'Democratic',
        'U': 'Unaffiliated',
        'I': 'Independent'
    }

    BASE_LEGISLATOR_URL = 'https://le.utah.gov/api/legislators'
    REPRESENTATIVE_URL = 'https://house.utah.gov/rep/{}'
    SENATOR_URL = 'https://senate.utah.gov/senator/{}'

    def scrape(self):
        try:
            legislators_response = self.session.get(self.BASE_LEGISLATOR_URL)
            legislators_data = json.loads(legislators_response.content)

            for legislator in legislators_data:
                person = self._process_legislator(legislator)
                if person:
                    yield person

        except requests.exceptions.RequestException as e:
            self.logger.error(f"Request failed: {e}")
        except json.JSONDecodeError as e:
            self.logger.error(f"JSON decoding error: {e}")

    def _process_legislator(self, legislator):
        try:
            full_name = f"{legislator.get('firstName', '')} {legislator.get('lastName', '')}"
            chamber = 'lower' if legislator.get('chamber') == 'House' else 'upper'
            party = self.PARTIES.get(legislator.get('party', 'U'), 'Unaffiliated')

            person = Person(
                name=full_name,
                district=str(legislator.get('district', 'N/A')),
                party=party
            )

            self._add_contact_details(person, legislator)
            self._add_sources_and_links(person, legislator)

            return person

        except Exception as e:
            self.logger.warning(f"Error processing legislator {full_name}: {e}")
            return None

    def _add_contact_details(self, person, legislator):
        contact_priority = [
            legislator.get('workPhone'),
            legislator.get('mobilePhone'),
            legislator.get('homePhone')
        ]

        email = legislator.get('email')
        phone = next((p for p in contact_priority if p), None)

        if validate_phone_number(phone):
            person.add_contact_detail(type='phone', value=phone, note='Work')

        if validate_email(email):
            person.add_contact_detail(type='email', value=email, note='Official')

    def _add_sources_and_links(self, person, legislator):
        chamber_url = (
            self.REPRESENTATIVE_URL.format(legislator.get('id')) 
            if legislator.get('chamber') == 'House' 
            else self.SENATOR_URL.format(legislator.get('id'))
        )

        person.add_source(self.BASE_LEGISLATOR_URL)
        person.add_link(url=chamber_url, note='Official Page')

        if legislator.get('financialDisclosureUrl'):
            person.add_link(
                url=legislator['financialDisclosureUrl'], 
                note='Financial Disclosure'
            )

def get_scraper():
    return UTPersonScraper()

