class IdentityValidationTest(test.NoDBTestCase):
    def setUp(self):
        super(IdentityValidationTest, self).setUp()
        self.context = mock.Mock()
        self.session_mock = mock.Mock(spec=session.Session)

    def _create_identity_client(self, response=None):
        if response is None:
            response = FakeResponse()

        def fake_get(url, *args, **kwargs):
            return response

        self.session_mock.get.side_effect = fake_get
        return self.session_mock

    def test_verify_project_id_success(self):
        project_id = 'valid_project_id'
        endpoint = 'http://keystone.example.com/v3/projects'
        session_mock = self._create_identity_client()

        result = self._verify_project_id(session_mock, project_id, endpoint)
        self.assertTrue(result)
        session_mock.get.assert_called_once_with(
            f'{endpoint}/{project_id}',
            raise_exc=False
        )

    def test_verify_project_id_not_found(self):
        project_id = 'nonexistent_project'
        endpoint = 'http://keystone.example.com/v3/projects'
        session_mock = self._create_identity_client(
            response=FakeResponse(status_code=404)
        )

        with self.assertRaises(exception.ProjectNotFound):
            self._verify_project_id(session_mock, project_id, endpoint)

    def test_verify_project_id_unauthorized(self):
        project_id = 'unauthorized_project'
        endpoint = 'http://keystone.example.com/v3/projects'
        session_mock = self._create_identity_client(
            response=FakeResponse(status_code=403)
        )

        with self.assertRaises(exception.PolicyNotAuthorized):
            self._verify_project_id(session_mock, project_id, endpoint)

    def test_verify_project_id_server_error(self):
        project_id = 'error_project'
        endpoint = 'http://keystone.example.com/v3/projects'
        session_mock = self._create_identity_client(
            response=FakeResponse(status_code=500)
        )

        with self.assertRaises(webob_exc.HTTPInternalServerError):
            self._verify_project_id(session_mock, project_id, endpoint)

    def _verify_project_id(self, session, project_id, endpoint):
        try:
            response = session.get(f'{endpoint}/{project_id}', raise_exc=False)
            if response:
                return True
            elif response.status_code == 404:
                raise exception.ProjectNotFound(project_id=project_id)
            elif response.status_code == 403:
                raise exception.PolicyNotAuthorized()
            elif response.status_code >= 500:
                raise webob_exc.HTTPInternalServerError()
            return False
        except Exception as e:
            raise e

import pytest
import psi4
import qcengine as qcng

class TestWaterOptimization:
    def setup_method(self):
        psi4.set_memory('2 GB')
        psi4.core.set_output_file('water_optimization.out', False)

    @pytest.mark.parametrize("method", ["scf", "mp2", "b3lyp"])
    @pytest.mark.parametrize("engine", ["optking", "geometric"])
    def test_water_optimization(self, method, engine):
        # Water molecule initial geometry
        h2o = psi4.geometry("""
        0 1
        O
        H 1 0.958
        H 1 0.958 2 104.5
        """)

        # Optimization configuration
        geometric_keywords = {
            "convergence": {
                "gmax": 1e-6,
                "grms": 1e-6,
                "dmax": 1e-3,
                "drms": 1e-3
            }
        }

        # Test input configuration
        inp = {
            "molecule": h2o,
            "method": method.upper(),
            "basis": "6-31G",
            "engine": engine
        }

        # Set quantum chemistry options
        psi4.set_options({
            "basis": inp["basis"],
            "scf_type": "df",
            "e_convergence": 1e-8,
            "d_convergence": 1e-8
        })

        # Perform optimization
        try:
            if inp["engine"] == "optking":
                opt_energy = psi4.optimize(inp["method"])
            elif inp["engine"] == "geometric":
                opt_energy = qcng.compute({
                    "molecule": h2o,
                    "method": inp["method"],
                    "basis": inp["basis"]
                }, "geometric")

            # Reference values for validation
            ref_energy = {
                "SCF": -76.0257,
                "MP2": -76.3215,
                "B3LYP": -76.4563
            }

            ref_nuclear_repulsion = 9.1561

            # Validate optimization results
            assert pytest.approx(opt_energy, rel=1e-4) == ref_energy[inp["method"].upper()]
            assert pytest.approx(
                psi4.core.get_active_molecule().nuclear_repulsion_energy(),
                rel=1e-4
            ) == ref_nuclear_repulsion

        except Exception as e:
            pytest.fail(f"Optimization failed for {method} with {engine}: {str(e)}")

    def teardown_method(self):
        psi4.core.clean()
        psi4.core.reset_output_file()

import os
import sys
import runpy
import importlib
import re
import logging
from typing import Dict, List, Any, Optional

class ModuleManager:
    def __init__(self, base_path: str):
        self.base_path = base_path
        self.modules: List[str] = []
        self.descriptions_modules: Dict[str, str] = {}
        self.modules_actifs: Dict[str, bool] = {}
        self.modules_par_defaut: Dict[str, bool] = {}
        self.logger = logging.getLogger(__name__)

    def _detecter_modules(self) -> None:
        try:
            modules_potentiels = [
                nom for nom in os.listdir(self.base_path)
                if os.path.isdir(os.path.join(self.base_path, nom))
                and not nom.startswith('__')
            ]

            for module_nom in modules_potentiels:
                chemin_module = os.path.join(self.base_path, module_nom)
                chemin_description = os.path.join(chemin_module, 'description.txt')

                if os.path.exists(chemin_description):
                    with open(chemin_description, 'r', encoding='utf-8') as fichier:
                        description = fichier.read().strip()

                    if self._valider_module(module_nom, description):
                        self.modules.append(module_nom)
                        self.descriptions_modules[module_nom] = description
                        self.modules_actifs[module_nom] = self.modules_par_defaut.get(module_nom, False)

        except Exception as e:
            self.err(f"Erreur lors de la détection des modules: {e}")

    def _valider_module(self, module_nom: str, description: str) -> bool:
        if not re.match(r'^[a-zA-Z0-9_]+$', module_nom):
            self.err(f"Nom de module invalide: {module_nom}")
            return False

        if len(description) > 500:
            self.err(f"Description trop longue pour le module {module_nom}")
            return False

        return True

    def _key(self, module: str) -> tuple:
        return (
            not self.modules_actifs.get(module, False),
            len(self.descriptions_modules.get(module, '')),
            module
        )

    def trier_modules(self) -> None:
        self.modules = sorted(self.modules, key=self._key)

    def charger_module(self, module_nom: str) -> Optional[Any]:
        if module_nom not in self.modules:
            self.err(f"Module non trouvé: {module_nom}")
            return None

        try:
            chemin_module = os.path.join(self.base_path, module_nom)
            sys.path.insert(0, chemin_module)

            module_charge = importlib.import_module(module_nom)
            sys.path.pop(0)

            return module_charge
        except ImportError as e:
            self.err(f"Impossible de charger le module {module_nom}: {e}")
            return None

    def activer_module(self, module_nom: str, actif: bool = True) -> bool:
        if module_nom not in self.modules:
            self.err(f"Module non trouvé: {module_nom}")
            return False

        self.modules_actifs[module_nom] = actif
        self.trier_modules()
        return True

    def lister_modules(self) -> List[str]:
        return [
            f"{module} ({'Actif' if self.modules_actifs[module] else 'Inactif'})"
            for module in self.modules
        ]

    def err(self, message: str) -> None:
        self.logger.error(message)

    def initialiser(self) -> None:
        self._detecter_modules()
        self.trier_modules()

def main():
    gestionnaire_modules = ModuleManager('/chemin/vers/modules')
    gestionnaire_modules.initialiser()

    print(gestionnaire_modules.lister_modules())
    module = gestionnaire_modules.charger_module('exemple')

    if module:
        module.executer()

if __name__ == '__main__':
    main()

import re
