import mod_helper

def sesamstrasseShow():
    oc = ObjectContainer(title2='Sesamstrasse Videos')
    urlMain = 'https://www.sesamstrasse.de/videos'

    try:
        html_content = mod_helper.get_html_content(urlMain)
        video_matches = re.findall(r'<video-item(.*?)</video-item>', html_content, re.DOTALL)

        for video_match in video_matches:
            title = re.search(r'title="(.*?)"', video_match)
            thumbnail = re.search(r'thumbnail="(.*?)"', video_match)
            duration_str = re.search(r'duration="(.*?)"', video_match)
            video_url = re.search(r'url="(.*?)"', video_match)

            if title and thumbnail and duration_str and video_url:
                title = title.group(1)
                thumbnail_url = thumbnail.group(1)
                duration_ms = int(duration_str.group(1))
                video_url = video_url.group(1)

                video_obj = sesamstrasseCreateVideoObject(
                    title, 
                    thumbnail_url, 
                    duration_ms, 
                    video_url
                )

                oc.add(video_obj)

    except Exception as e:
        mod_helper.log_error(f"Error fetching Sesamstrasse videos: {str(e)}")

    return oc

def sesamstrasseCreateVideoObject(title, thumbnail, duration, video_url):
    video_obj = VideoClipObject(
        title=title,
        thumb=thumbnail,
        duration=duration,
        items=[
            MediaObject(
                parts=[
                    PartObject(
                        key=Callback(
                            sesamstrasseGetStreamingUrl, 
                            url=video_url
                        )
                    )
                ],
                protocol='http',
                container='mp4',
                video_codec='h264',
                audio_codec='aac'
            )
        ]
    )

    return video_obj

def sesamstrasseGetStreamingUrl(url):
    try:
        stream_data = mod_helper.fetch_stream_metadata(url)

        # Prioritize stream qualities
        stream_qualities = [
            stream_data.get('high_quality'),
            stream_data.get('medium_quality'),
            stream_data.get('low_quality')
        ]

        for quality_url in stream_qualities:
            if quality_url and mod_helper.validate_stream_url(quality_url):
                return Redirect(quality_url)

        raise Exception("No valid stream URL found")

    except Exception as e:
        mod_helper.log_error(f"Stream URL retrieval error: {str(e)}")
        return None

