import os
import subprocess
import shlex

class ShellCommandGenerator:
    HADOOP_CONF_DIR = os.environ.get('HADOOP_CONF_DIR', '/etc/hadoop/conf')

    @staticmethod
    def exists(command):
        """Check if a command exists in the system path."""
        try:
            subprocess.run(['which', command], 
                           stdout=subprocess.PIPE, 
                           stderr=subprocess.PIPE, 
                           check=True)
            return True
        except subprocess.CalledProcessError:
            return False

    @staticmethod
    def encrypt(input_file, output_file, method='openssl', key=None):
        """Generate encryption command."""
        if method == 'openssl' and ShellCommandGenerator.exists('openssl'):
            if not key:
                raise ValueError("Encryption key is required")
            return f"openssl enc -aes-256-cbc -salt -in {input_file} -out {output_file} -pass pass:{key}"

        if method == 'gpg' and ShellCommandGenerator.exists('gpg'):
            return f"gpg -c {input_file} -o {output_file}"

        raise RuntimeError(f"No encryption method available: {method}")

    @staticmethod
    def decrypt(input_file, output_file, method='openssl', key=None):
        """Generate decryption command."""
        if method == 'openssl' and ShellCommandGenerator.exists('openssl'):
            if not key:
                raise ValueError("Decryption key is required")
            return f"openssl enc -d -aes-256-cbc -in {input_file} -out {output_file} -pass pass:{key}"

        if method == 'gpg' and ShellCommandGenerator.exists('gpg'):
            return f"gpg -d {input_file} -o {output_file}"

        raise RuntimeError(f"No decryption method available: {method}")

    @staticmethod
    def compress(input_path, output_path, method='gzip'):
        """Generate compression command."""
        compression_methods = {
            'gzip': f"gzip -c {input_path} > {output_path}",
            'bzip2': f"bzip2 -c {input_path} > {output_path}",
            'xz': f"xz -c {input_path} > {output_path}",
            'zip': f"zip {output_path} {input_path}"
        }

        if method not in compression_methods:
            raise ValueError(f"Unsupported compression method: {method}")

        return compression_methods[method]

    @staticmethod
    def decompress(input_path, output_path=None, method=None):
        """Generate decompression command."""
        if not method:
            if input_path.endswith('.gz'):
                method = 'gzip'
            elif input_path.endswith('.bz2'):
                method = 'bzip2'
            elif input_path.endswith('.xz'):
                method = 'xz'
            elif input_path.endswith('.zip'):
                method = 'unzip'

        decomp_methods = {
            'gzip': f"gzip -d -c {input_path} > {output_path or input_path[:-3]}",
            'bzip2': f"bzip2 -d -c {input_path} > {output_path or input_path[:-4]}",
            'xz': f"xz -d -c {input_path} > {output_path or input_path[:-3]}",
            'unzip': f"unzip {input_path} -d {output_path or os.path.dirname(input_path)}"
        }

        if method not in decomp_methods:
            raise ValueError(f"Unsupported decompression method: {method}")

        return decomp_methods[method]

    @staticmethod
    def hdfs_cat(hdfs_path, hadoop_bin='hadoop'):
        """Generate HDFS cat command."""
        return f"{hadoop_bin} fs -cat {hdfs_path}"

    @staticmethod
    def pv(input_file, total_size=None):
        """Generate progress view command."""
        if not ShellCommandGenerator.exists('pv'):
            return f"cat {input_file}"

        if total_size:
            return f"pv -s {total_size} {input_file}"

        return f"pv {input_file}"

    @staticmethod
    def tar(source_dir, output_file, compression='gz'):
        """Generate tar archiving command."""
        compression_flag = {
            'gz': 'z',
            'bz2': 'j',
            'xz': 'J'
        }.get(compression, 'z')

        return f"tar -c{compression_flag}vf {output_file} {source_dir}"

    @staticmethod
    def untar(archive_file, output_dir=None, compression='gz'):
        """Generate tar extraction command."""
        compression_flag = {
            'gz': 'z',
            'bz2': 'j',
            'xz': 'J'
        }.get(compression, 'z')

        extract_cmd = f"tar -x{compression_flag}vf {archive_file}"

        if output_dir:
            extract_cmd += f" -C {output_dir}"

        return extract_cmd

import iris
import pyugrid
import cartopy.crs as ccrs
import cartopy.feature as cfeature
import numpy as np
import matplotlib.pyplot as plt
from iris.coords import AuxCoord
from scipy.spatial import Delaunay

class OceanModelComparator:
    def __init__(self):
        self.name_list = [
            'sea_surface_height', 'ssh', 'elevation', 
            'zeta', 'water_surface_height'
        ]
        self.models = {
            'ADCIRC': 'https://example.com/adcirc_data.nc',
            'FVCOM': 'https://example.com/fvcom_data.nc',
            'SELFE': 'https://example.com/selfe_data.nc',
            'WW3': 'https://example.com/ww3_data.nc'
        }
        self.cubes = {}
        self.tris = {}

    def cube_func(self, cube):
        """Custom constraint function for extracting sea surface elevation."""
        for name in self.name_list:
            if name in cube.name().lower():
                return True
        return False

    def get_mesh(self, cube):
        """Extract mesh information from UGRID-compliant NetCDF."""
        try:
            mesh = pyugrid.UGrid.from_netCDF_file(cube.filename)
            return mesh
        except Exception as e:
            print(f"Mesh extraction error: {e}")
            return None

    def get_triang(self, mesh):
        """Create triangulation from mesh coordinates."""
        if mesh is None:
            return None
        return Delaunay(mesh.nodes)

    def load_model_data(self):
        """Load sea surface elevation data for multiple models."""
        for model_name, url in self.models.items():
            try:
                constraint = iris.Constraint(self.cube_func)
                cube = iris.load_cube(url, constraint)

                # Select last time index if multiple time steps exist
                if cube.ndim > 2:
                    cube = cube[-1, :]

                self.cubes[model_name] = cube

                mesh = self.get_mesh(cube)
                self.tris[model_name] = self.get_triang(mesh)

            except Exception as e:
                print(f"Error loading {model_name} data: {e}")

    def plot_model(self, model_name, ax=None):
        """Visualize sea surface elevation on geographical context."""
        if model_name not in self.cubes or model_name not in self.tris:
            print(f"Data for {model_name} not available")
            return

        cube = self.cubes[model_name]
        triang = self.tris[model_name]

        if ax is None:
            fig, ax = plt.subplots(figsize=(12, 8), 
                                   subplot_kw={'projection': ccrs.PlateCarree()})

        ax.add_feature(cfeature.COASTLINE)
        ax.add_feature(cfeature.BORDERS, linestyle=':')

        # Extract longitude, latitude, and elevation data
        lons = cube.coord('longitude').points
        lats = cube.coord('latitude').points
        values = cube.data

        # Triangular mesh plot
        scatter = ax.tricontourf(lons, lats, triang.simplices, values, 
                                 transform=ccrs.PlateCarree(), 
                                 cmap='viridis')
        plt.colorbar(scatter, ax=ax, label='Sea Surface Elevation (m)')

        ax.set_title(f'Sea Surface Elevation: {model_name}')
        return ax

    def multi_model_comparison(self):
        """Compare sea surface elevation across multiple models."""
        self.load_model_data()

        fig, axes = plt.subplots(2, 2, figsize=(16, 12), 
                                 subplot_kw={'projection': ccrs.PlateCarree()})
        axes = axes.ravel()

        for idx, model_name in enumerate(self.models.keys()):
            self.plot_model(model_name, ax=axes[idx])

        plt.tight_layout()
        plt.show()

def main():
    comparator = OceanModelComparator()
    comparator.multi_model_comparison()

if __name__ == "__main__":
    main()

from abc import ABC, abstractmethod
from typing import Dict, List, Optional
import random

class FieldNodeItem(ABC):
    def __init__(self, name: str, material: str, x: int, y: int):
        self.name = name
        self.material = material
        self.x = x
        self.y = y
        self.health = 100
        self.age = 0
        self.resources: Dict[str, int] = {}

    @abstractmethod
    def update(self):
        pass

    @abstractmethod
    def harvest(self) -> Dict[str, int]:
        return {}

    def score(self) -> float:
        material_multipliers = {
            'wood': 1.2,
            'stone': 1.5,
            'metal': 2.0
        }
        base_score = len(self.resources) * 10
        return base_score * material_multipliers.get(self.material, 1.0)

    def describe(self) -> str:
        return f"{self.name} ({self.material}) at [{self.x}, {self.y}]"

    def __repr__(self) -> str:
        return self.describe()

class RoomItem(FieldNodeItem):
    def __init__(self, name: str, material: str, x: int, y: int, capacity: int = 5):
        super().__init__(name, material, x, y)
        self.capacity = capacity
        self.occupants: List[str] = []

    def update(self):
        self.age += 1
        self.health = max(0, self.health - random.uniform(0.5, 1.5))

    def harvest(self) -> Dict[str, int]:
        return {'shelter': len(self.occupants)}

    def add_occupant(self, occupant: str) -> bool:
        if len(self.occupants) < self.capacity:
            self.occupants.append(occupant)
            return True
        return False

class StableItem(FieldNodeItem):
    def __init__(self, name: str, material: str, x: int, y: int):
        super().__init__(name, material, x, y)
        self.animals: Dict[str, int] = {
            'horse': 0,
            'cow': 0,
            'sheep': 0
        }

    def update(self):
        self.age += 1
        self.update_animals()

    def update_animals(self):
        for animal, count in self.animals.items():
            if random.random() < 0.1:
                self.animals[animal] += 1
            elif random.random() < 0.05 and count > 0:
                self.animals[animal] -= 1

    def harvest(self) -> Dict[str, int]:
        total_animals = sum(self.animals.values())
        return {
            'meat': total_animals,
            'leather': total_animals // 2
        }

class PlowedFieldItem(FieldNodeItem):
    def __init__(self, name: str, material: str, x: int, y: int):
        super().__init__(name, material, x, y)
        self.crops: Dict[str, int] = {
            'wheat': 0,
            'corn': 0,
            'potato': 0
        }
        self.water_level = 50

    def update(self):
        self.age += 1
        self.update_crop()
        self.water_level = max(0, min(100, self.water_level + random.uniform(-5, 5)))

    def update_crop(self):
        for crop, growth in self.crops.items():
            growth_rate = 1 if self.water_level > 30 else 0.5
            self.crops[crop] = min(100, growth + growth_rate)

    def harvest(self) -> Dict[str, int]:
        harvested = {}
        for crop, value in self.crops.items():
            if value >= 80:
                harvested[crop] = int(value / 10)
                self.crops[crop] = 0
        return harvested

