from datetime import datetime, timedelta
from typing import Dict, Any, Optional
import re

class TodoBase:
    def __init__(self, text: str):
        self.text = text
        self.attributes = self._parse_attributes()

    def _parse_attributes(self) -> Dict[str, Any]:
        # Base parsing logic for todo item attributes
        attributes = {}
        return attributes

class Config:
    DATE_TAGS = {
        'start': ['started', 'begin', 'start'],
        'due': ['due', 'deadline', 'by'],
        'completed': ['done', 'completed']
    }
    DEFAULT_DATE_FORMAT = '%Y-%m-%d'

class Utils:
    @staticmethod
    def parse_date(date_str: str) -> Optional[datetime]:
        try:
            return datetime.strptime(date_str, Config.DEFAULT_DATE_FORMAT)
        except ValueError:
            try:
                return datetime.today().replace(day=int(date_str))
            except ValueError:
                return None

class Todo(TodoBase):
    def __init__(self, text: str):
        super().__init__(text)
        self.attributes['start'] = self.start_date()
        self.attributes['due'] = self.due_date()
        self.attributes['completed'] = self.is_completed()

    def _parse_attributes(self) -> Dict[str, Any]:
        attributes = {}
        tags = self.text.split()

        for tag in tags:
            for category, patterns in Config.DATE_TAGS.items():
                for pattern in patterns:
                    if tag.startswith(f'{pattern}:'):
                        attributes[category] = tag.split(':')[1]

        return attributes

    def get_date(self, category: str) -> Optional[datetime]:
        date_str = self.attributes.get(category)
        return Utils.parse_date(date_str) if date_str else None

    def start_date(self) -> Optional[datetime]:
        return self.get_date('start')

    def due_date(self) -> Optional[datetime]:
        return self.get_date('due')

    def is_completed(self) -> bool:
        return any(tag in self.text for tag in Config.DATE_TAGS['completed'])

    def is_active(self) -> bool:
        start = self.start_date()
        due = self.due_date()
        today = datetime.today()

        return (not self.is_completed() and 
                (start is None or start <= today) and 
                (due is None or due >= today))

    def is_overdue(self) -> bool:
        due = self.due_date()
        today = datetime.today()

        return (due is not None and 
                today > due and 
                not self.is_completed())

    def days_till_due(self) -> Optional[int]:
        due = self.due_date()
        today = datetime.today()

        return (due - today).days if due is not None else None

    def length(self) -> Optional[timedelta]:
        start = self.start_date()
        due = self.due_date()

        return due - start if start and due else None

    def __repr__(self) -> str:
        return f"Todo(text='{self.text}', start={self.start_date()}, due={self.due_date()})"

def main():
    # Example usage and demonstration
    todo_items = [
        Todo("Complete project started:2023-06-01 due:2023-07-15"),
        Todo("Review documentation by:2023-06-30"),
        Todo("Implement feature start:15 deadline:2023-08-01"),
        Todo("Team meeting done:2023-06-10")
    ]

    for todo in todo_items:
        print(f"Todo: {todo.text}")
        print(f"Active: {todo.is_active()}")
        print(f"Overdue: {todo.is_overdue()}")
        print(f"Days till due: {todo.days_till_due()}")
        print("---")

if __name__ == "__main__":
    main()

import os
import sys
import json
import urllib
from urllib.parse import urlparse, urlencode, urlunparse

class RequestHandler:
    def __init__(self, request_data=None):
        self.request = request_data or {}
        self.response = {
            'headers': {},
            'status_code': 200,
            'body': None
        }
        self.server_data = {
            'environment': os.environ,
            'pid': os.getpid(),
            'cwd': os.getcwd()
        }

    def get_template(self, template_type='default'):
        templates = {
            'default': {
                'message': 'Generic Response',
                'status': 200
            },
            'redirect': {
                'message': 'Redirecting...',
                'status': 302
            }
        }
        return templates.get(template_type, templates['default'])

    def get_swapped_origin_netloc(self, original_url, target_origin=None):
        parsed_url = urlparse(original_url)
        if target_origin:
            target_parsed = urlparse(target_origin)
            swapped_netloc = f"{target_parsed.scheme}://{target_parsed.netloc}"
        else:
            swapped_netloc = f"{parsed_url.scheme}://{parsed_url.netloc}"
        return swapped_netloc

    def create_redirect_url(self, base_url, params=None, swap_origin=False, target_origin=None):
        parsed_url = urlparse(base_url)

        if swap_origin and target_origin:
            swapped_netloc = self.get_swapped_origin_netloc(base_url, target_origin)
            parsed_url = parsed_url._replace(netloc=swapped_netloc.split('://')[1])

        if params:
            query_params = urlencode(params)
            parsed_url = parsed_url._replace(query=query_params)

        return urlunparse(parsed_url)

    def redirect(self, target_url, params=None, permanent=False):
        redirect_template = self.get_template('redirect')
        self.response.update({
            'status_code': 301 if permanent else 302,
            'headers': {
                'Location': self.create_redirect_url(target_url, params)
            },
            'body': redirect_template['message']
        })
        return self.response

    def preprocess_redirection(self, request_params):
        redirection_config = {
            'enabled': request_params.get('redirect', False),
            'target_url': request_params.get('target_url'),
            'swap_origin': request_params.get('swap_origin', False),
            'target_origin': request_params.get('target_origin')
        }
        return redirection_config

    def respond(self, content=None, status_code=200, headers=None):
        response_template = self.get_template()
        self.response.update({
            'status_code': status_code or response_template['status'],
            'headers': headers or {},
            'body': content or response_template['message']
        })
        return self.response

def main():
    request_data = {
        'method': 'GET',
        'path': '/test',
        'query_params': {
            'redirect': True,
            'target_url': 'https://example.com/destination',
            'swap_origin': True
        }
    }

    handler = RequestHandler(request_data)

    redirection_config = handler.preprocess_redirection(request_data.get('query_params', {}))

    if redirection_config['enabled'] and redirection_config['target_url']:
        response = handler.redirect(
            redirection_config['target_url'],
            params={'origin_swapped': True},
            permanent=False
        )
    else:
        response = handler.respond(
            content='Default Response',
            status_code=200,
            headers={'X-Custom-Header': 'RequestHandler'}
        )

    print(json.dumps(response, indent=2))

if __name__ == '__main__':
    main()

import re
import click
import requests
from bs4 import BeautifulSoup
from terminaltables import AsciiTable

USER_AGENT = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
}

def quick_search(search_term):
    base_url = "https://ark.intel.com/content/www/us/en/ark/search.html"
    params = {'q': search_term}
    try:
        response = requests.get(base_url, params=params, headers=USER_AGENT)
        soup = BeautifulSoup(response.text, 'html.parser')
        results = soup.find_all('div', class_='ark-product-name')

        choice_dict = {}
        for idx, result in enumerate(results, 1):
            product_name = result.get_text(strip=True)
            product_link = result.find('a')['href']
            choice_dict[idx] = (product_name, product_link)

        return choice_dict
    except requests.exceptions.RequestException as e:
        click.echo(f"Error during search: {e}")
        return {}

def get_cpu_html(url):
    full_url = f"https://ark.intel.com{url}"
    try:
        response = requests.get(full_url, headers=USER_AGENT)
        return response.text
    except requests.exceptions.RequestException as e:
        click.echo(f"Error fetching processor details: {e}")
        return None

def generate_table_data(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')
    ark_json = {}

    specs_sections = soup.find_all('div', class_='specs-section')
    for section in specs_sections:
        section_title = section.find('h2')
        if section_title:
            section_name = section_title.get_text(strip=True)
            specs = section.find_all('div', class_='spec-item')
            for spec in specs:
                key = spec.find('dt').get_text(strip=True)
                value = spec.find('dd').get_text(strip=True)
                ark_json[key] = value

    table_data = [
        ['Specification', 'Value'],
        *[[key, value] for key, value in ark_json.items()]
    ]
    return table_data

@click.command()
@click.argument('search_term')
def search(search_term):
    click.echo(f"Searching for processors matching: {search_term}")
    results = quick_search(search_term)

    if not results:
        click.echo("No processors found.")
        return

    for idx, (name, _) in results.items():
        click.echo(f"{idx}. {name}")

    try:
        choice = click.prompt("Select a processor number", type=int)
        if choice not in results:
            click.echo("Invalid selection.")
            return

        _, url = results[choice]
        html_content = get_cpu_html(url)

        if html_content:
            table_data = generate_table_data(html_content)
            table = AsciiTable(table_data)
            table.title = results[choice][0]
            click.echo(table.table)
    except ValueError:
        click.echo("Invalid input.")

if __name__ == '__main__':
    search()

import SoftLayer
import logging
from typing import List, Dict, Any, Iterator

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s: %(message)s'
)
logger = logging.getLogger(__name__)

class IterableItems:
    def __init__(self, client, service, mask=None, filter=None):
        self.client = client
        self.service = service
        self.mask = mask
        self.filter = filter
        self.offset = 0
        self.limit = 100
        self.total_count = None

    def _fetch_data(self) -> List[Dict[str, Any]]:
        try:
            kwargs = {
                'offset': self.offset,
                'limit': self.limit
            }
            if self.mask:
                kwargs['mask'] = self.mask
            if self.filter:
                kwargs['filter'] = self.filter

            result = self.service.getObject(**kwargs)
            self.total_count = result.get('totalCount', len(result))
            return result.get('items', result)
        except Exception as e:
            logger.error(f"Error fetching data: {e}")
            return []

    def __iter__(self):
        return self

    def __next__(self):
        if self.total_count is not None and self.offset >= self.total_count:
            raise StopIteration

        items = self._fetch_data()
        if not items:
            raise StopIteration

        self.offset += self.limit
        return items

class Users(IterableItems):
    def __init__(self, client):
        super().__init__(
            client,
            client['Account'].getUsers,
            mask='id,username,email,firstName,lastName'
        )

class VirtualGuests(IterableItems):
    def __init__(self, client):
        super().__init__(
            client,
            client['Account'].getVirtualGuests,
            mask='id,hostname,domain,primaryBackendIpAddress,primaryIpAddress'
        )

def initialize_client(username: str, api_key: str) -> Dict[str, Any]:
    """Initialize SoftLayer client with credentials."""
    try:
        return SoftLayer.create_client_from_env(
            username=username,
            api_key=api_key
        )
    except Exception as e:
        logger.error(f"Client initialization error: {e}")
        return None

def list_instances(client) -> List[Dict[str, Any]]:
    """Retrieve and display all virtual instances."""
    try:
        instances = VirtualGuests(client)
        all_instances = []
        for chunk in instances:
            all_instances.extend(chunk)
        return all_instances
    except Exception as e:
        logger.error(f"Error listing instances: {e}")
        return []

def get_billing_items(client) -> List[Dict[str, Any]]:
    """Retrieve billing items for the account."""
    try:
        return client['Account'].getAllBillingItems()
    except Exception as e:
        logger.error(f"Error retrieving billing items: {e}")
        return []

def display_user_details(users: List[Dict[str, Any]]) -> None:
    """Display user account details."""
    print("\n--- User Accounts ---")
    for user in users:
        print(f"Username: {user.get('username', 'N/A')}")
        print(f"Email: {user.get('email', 'N/A')}")
        print(f"Name: {user.get('firstName', '')} {user.get('lastName', '')}\n")

def display_instance_details(instances: List[Dict[str, Any]]) -> None:
    """Display virtual guest instance details."""
    print("\n--- Virtual Instances ---")
    for instance in instances:
        print(f"Hostname: {instance.get('hostname', 'N/A')}")
        print(f"Domain: {instance.get('domain', 'N/A')}")
        print(f"Primary IP: {instance.get('primaryIpAddress', 'N/A')}\n")

def main():
    """Main execution method for SoftLayer account information retrieval."""
    # Replace with actual credentials
    USERNAME = 'your_softlayer_username'
    API_KEY = 'your_softlayer_api_key'

    # Initialize client
    client = initialize_client(USERNAME, API_KEY)
    if not client:
        logger.error("Could not initialize SoftLayer client")
        return

    try:
        # Retrieve and display user details
        users = list(Users(client))
        display_user_details([user for sublist in users for user in sublist])

        # Retrieve and display instance details
        instances = list_instances(client)
        display_instance_details(instances)

        # Retrieve and log billing items
        billing_items = get_billing_items(client)
        logger.info(f"Total Billing Items: {len(billing_items)}")

    except Exception as e:
        logger.error(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()

