import json
import datetime
import pytz
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_protect
from sqlalchemy import Column, Integer, String, DateTime, Text
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
from sqlalchemy import create_engine

Base = declarative_base()
engine = create_engine('sqlite:///content_database.db')
DBSession = sessionmaker(bind=engine)

class Article(Base):
    __tablename__ = 'articles'
    id = Column(Integer, primary_key=True)
    title = Column(String(250), nullable=False)
    content = Column(Text)
    author = Column(String(100))
    published_date = Column(DateTime)
    category = Column(String(50))
    thumbnail = Column(String(250))
    video_url = Column(String(250))
    platform = Column(String(50))

Base.metadata.create_all(engine)

def get_utc_timestamp():
    return datetime.datetime.now(pytz.UTC)

def getrelate(article_id, category):
    session = DBSession()
    related_articles = session.query(Article).filter(
        Article.category == category,
        Article.id != article_id
    ).limit(5).all()
    session.close()
    return [
        {
            'id': article.id,
            'title': article.title,
            'thumbnail': article.thumbnail
        } for article in related_articles
    ]

def get_home_data(request):
    session = DBSession()
    page = int(request.GET.get('page', 1))
    per_page = int(request.GET.get('per_page', 10))
    category = request.GET.get('category', None)

    query = session.query(Article)
    if category:
        query = query.filter(Article.category == category)

    total_articles = query.count()
    articles = query.order_by(Article.published_date.desc()) \
        .offset((page - 1) * per_page) \
        .limit(per_page).all()

    session.close()
    return JsonResponse({
        'articles': [
            {
                'id': article.id,
                'title': article.title,
                'author': article.author,
                'thumbnail': article.thumbnail,
                'published_date': article.published_date.isoformat()
            } for article in articles
        ],
        'total_pages': (total_articles + per_page - 1) // per_page,
        'current_page': page
    })

@csrf_protect
def get_article_content(request, article_id):
    session = DBSession()
    article = session.query(Article).filter(Article.id == article_id).first()

    if not article:
        session.close()
        return JsonResponse({'error': 'Article not found'}, status=404)

    related_articles = getrelate(article_id, article.category)
    session.close()

    return JsonResponse({
        'id': article.id,
        'title': article.title,
        'content': article.content,
        'author': article.author,
        'published_date': article.published_date.isoformat(),
        'thumbnail': article.thumbnail,
        'related_articles': related_articles
    })

def get_video_realUrl(request, video_id):
    session = DBSession()
    video_entry = session.query(Article).filter(Article.id == video_id).first()

    if not video_entry:
        session.close()
        return JsonResponse({'error': 'Video not found'}, status=404)

    platform_resolvers = {
        'youtube': resolve_youtube_url,
        'vimeo': resolve_vimeo_url,
        'dailymotion': resolve_dailymotion_url
    }

    resolver = platform_resolvers.get(video_entry.platform.lower())
    if not resolver:
        session.close()
        return JsonResponse({'error': 'Unsupported platform'}, status=400)

    real_url = resolver(video_entry.video_url)
    session.close()

    return JsonResponse({
        'video_url': real_url,
        'platform': video_entry.platform
    })

def resolve_youtube_url(url):
    # YouTube URL resolution logic
    return url.replace('watch?v=', 'embed/')

def resolve_vimeo_url(url):
    # Vimeo URL resolution logic
    return url.replace('vimeo.com/', 'player.vimeo.com/video/')

def resolve_dailymotion_url(url):
    # Dailymotion URL resolution logic
    return url.replace('dailymotion.com/video/', 'dailymotion.com/embed/video/')

import logging
from django.utils.translation import ugettext_lazy as _
from django.core.urlresolvers import reverse
from horizon import tables
from horizon import views
from horizon import exceptions

from openstack_dashboard import api
from openstack_dashboard.dashboards.identity.users import constants

LOG = logging.getLogger(__name__)

class OrganizationsTable(tables.DataTable):
    name = tables.Column('name', verbose_name=_('Organization Name'),
                         link='horizon:identity:organizations:detail')
    description = tables.Column('description', verbose_name=_('Description'))
    enabled = tables.Column('enabled', verbose_name=_('Enabled'),
                            filters=(lambda x: 'Yes' if x else 'No',))

    class Meta(object):
        name = "organizations"
        verbose_name = _("Organizations")
        column_defaults = {'sortable': True}
        row_actions = []
        multi_select = False

class ApplicationsTable(tables.DataTable):
    name = tables.Column('name', verbose_name=_('Application Name'),
                         link='horizon:identity:applications:detail')
    description = tables.Column('description', verbose_name=_('Description'))
    status = tables.Column('status', verbose_name=_('Status'))

    class Meta(object):
        name = "applications"
        verbose_name = _("Applications")
        column_defaults = {'sortable': True}
        row_actions = []
        multi_select = False

class IndexView(views.APIView):
    template_name = 'identity/home/index.html'

    def dispatch(self, request, *args, **kwargs):
        try:
            # Perform initial authorization and organization validation
            user_organizations = self.get_organizations_data(request)

            if not user_organizations:
                return self.handle_no_organizations(request)

            current_org = request.session.get('current_organization')

            if not current_org or current_org not in [org.id for org in user_organizations]:
                return self.redirect_to_default_organization(request, user_organizations)

            return super(IndexView, self).dispatch(request, *args, **kwargs)

        except Exception as e:
            LOG.error(f"Error in home dashboard dispatch: {str(e)}")
            exceptions.handle(request, _('Unable to retrieve organizations.'))
            return None

    def get_organizations_data(self, request):
        try:
            organizations = api.keystone.organizations_list(request)
            return [org for org in organizations if org.enabled]
        except Exception as e:
            LOG.error(f"Failed to retrieve organizations: {str(e)}")
            return []

    def get_applications_data(self, request):
        try:
            current_org = request.session.get('current_organization')
            applications = api.keystone.applications_list(request, organization_id=current_org)
            return applications
        except Exception as e:
            LOG.error(f"Failed to retrieve applications: {str(e)}")
            return []

    def handle_no_organizations(self, request):
        LOG.warning("User has no organizations")
        return views.redirect(reverse('horizon:identity:registration:index'))

    def redirect_to_default_organization(self, request, organizations):
        default_org = organizations[0]
        request.session['current_organization'] = default_org.id
        return views.redirect(reverse('horizon:identity:home:index'))

    def get_context_data(self, **kwargs):
        context = super(IndexView, self).get_context_data(**kwargs)

        try:
            context['organizations'] = self.get_organizations_data(self.request)
            context['applications'] = self.get_applications_data(self.request)
        except Exception as e:
            LOG.error(f"Context data retrieval error: {str(e)}")
            context['organizations'] = []
            context['applications'] = []

        context['organizations_table'] = OrganizationsTable(
            self.request, context['organizations'])
        context['applications_table'] = ApplicationsTable(
            self.request, context['applications'])

        return context

import os
import importlib
import yaml
import pkg_resources
from flask_registry import Registry, RegistryProxy, ModuleAutoDiscoveryRegistry, PkgResourcesDirDiscoveryRegistry
from typing import Dict, List, Callable, Any

class LazyDict(dict):
    def __init__(self, loader_func):
        self._loader_func = loader_func
        self._loaded = False
        super().__init__()

    def __getitem__(self, key):
        if not self._loaded:
            self._loader_func(self)
            self._loaded = True
        return super().__getitem__(key)

    def __contains__(self, key):
        if not self._loaded:
            self._loader_func(self)
            self._loaded = True
        return super().__contains__(key)

def discover_format_templates(registry: List[str]) -> Dict[str, str]:
    templates = {}
    for base_dir in registry:
        for root, _, files in os.walk(base_dir):
            for file in files:
                if file.endswith(('.html', '.txt', '.md')):
                    template_name = os.path.splitext(file)[0]
                    template_path = os.path.join(root, file)
                    templates[template_name] = template_path
    return templates

def discover_output_formats(registry: List[str]) -> Dict[str, Dict[str, Any]]:
    formats = {}
    for base_dir in registry:
        yaml_files = [f for f in os.listdir(base_dir) if f.endswith('.yaml') or f.endswith('.yml')]
        for yaml_file in yaml_files:
            file_path = os.path.join(base_dir, yaml_file)
            with open(file_path, 'r') as f:
                config = yaml.safe_load(f)
                format_name = os.path.splitext(yaml_file)[0]
                formats[format_name] = config
    return formats

def create_format_templates_lookup(registry_bases: List[str]) -> LazyDict:
    def loader(lazy_dict):
        templates = discover_format_templates(registry_bases)
        lazy_dict.update(templates)

    return LazyDict(loader)

def create_output_formats_lookup(registry_bases: List[str]) -> LazyDict:
    def loader(lazy_dict):
        formats = discover_output_formats(registry_bases)
        lazy_dict.update(formats)

    return LazyDict(loader)

def filter_html_formats(formats: Dict[str, Any]) -> Dict[str, Any]:
    return {k: v for k, v in formats.items() if not v.get('is_html', False)}

def register_template_contexts():
    template_context_functions = {}

    def register_context_func(name: str):
        def decorator(func: Callable):
            template_context_functions[name] = func
            return func
        return decorator

    return register_context_func

