class CKEditorWidget(forms.Textarea):
    def __init__(self, config_name='default', *args, **kwargs):
        self.config_name = config_name
        attrs = kwargs.get('attrs', {})
        super(CKEditorWidget, self).__init__(*args, **kwargs)

        self.attrs.update(attrs)
        self.attrs['class'] = self.attrs.get('class', '') + ' ckeditor'

    def get_config(self):
        try:
            config = getattr(settings, 'CKEDITOR_CONFIGS', {}).get(
                self.config_name, DEFAULT_CONFIG
            )
            return {**DEFAULT_CONFIG, **config}
        except Exception as e:
            return DEFAULT_CONFIG

    def _get_upload_urls(self):
        try:
            upload_url = settings.CKEDITOR_UPLOAD_PATH
            browse_url = settings.CKEDITOR_BROWSE_URL
            return upload_url, browse_url
        except AttributeError:
            return '', ''

    def render(self, name, value, attrs=None, renderer=None):
        final_attrs = self.build_attrs(self.attrs, attrs)
        config = self.get_config()
        upload_url, browse_url = self._get_upload_urls()

        config.update({
            'filebrowserUploadUrl': upload_url,
            'filebrowserBrowseUrl': browse_url
        })

        final_attrs['data-ckeditor-config'] = mark_safe(
            json.dumps(config)
        )

        rendered = super(CKEditorWidget, self).render(
            name, value, final_attrs, renderer
        )

        context = {
            'final_attrs': final_attrs,
            'name': name,
            'config': config,
            'rendered_textarea': rendered
        }

        return mark_safe(render_to_string(
            'ckeditor/widget.html', context
        ))

    class Media:
        js = (
            'ckeditor/ckeditor.js',
            'ckeditor/init.js',
        )
        css = {
            'all': ('ckeditor/ckeditor.css',)
        }

