import uuid
from datetime import datetime
from oauth2client.service_account import ServiceAccountCredentials
from googleapiclient.discovery import build

class BusinessMessageService:
    def __init__(self, service_account_path):
        self.credentials = self._authenticate_service_account(service_account_path)
        self.business_messages_service = build('businessmessages', 'v1', credentials=self.credentials)

    def _authenticate_service_account(self, service_account_path):
        """Authenticate using service account credentials."""
        scopes = ['https://www.googleapis.com/auth/businessmessages']
        try:
            credentials = ServiceAccountCredentials.from_json_keyfile_name(
                service_account_path, 
                scopes=scopes
            )
            return credentials
        except Exception as auth_error:
            print(f"Authentication Error: {auth_error}")
            return None

    def create_dial_suggestion(self, phone_number, display_text):
        """Create a phone dial suggestion action."""
        return {
            'suggestion': {
                'action': {
                    'text': display_text,
                    'dialAction': {
                        'phoneNumber': phone_number
                    }
                }
            }
        }

    def generate_message_id(self):
        """Generate a unique message identifier."""
        return str(uuid.uuid4())

    def send_support_message(
        self, 
        conversation_id, 
        message_text, 
        phone_number, 
        representative_type='BOT'
    ):
        """Send a support message with dial suggestion."""
        try:
            message = {
                'messageId': self.generate_message_id(),
                'representative': {
                    'representativeType': representative_type
                },
                'text': message_text,
                'fallbackText': 'Unable to display rich message. Please contact support.',
                'suggestions': [
                    self.create_dial_suggestion(
                        phone_number, 
                        'Call Customer Support'
                    )
                ]
            }

            request = self.business_messages_service.conversations().messages().create(
                parent=f'conversations/{conversation_id}',
                body=message
            )

            response = request.execute()
            return {
                'status': 'success',
                'message_id': response.get('name', ''),
                'timestamp': datetime.now().isoformat()
            }

        except Exception as send_error:
            return {
                'status': 'error',
                'message': str(send_error),
                'timestamp': datetime.now().isoformat()
            }

def main():
    # Example usage
    service_account_path = '/path/to/service_account.json'
    conversation_id = 'user_conversation_identifier'
    support_phone = '+1234567890'

    message_service = BusinessMessageService(service_account_path)

    support_message = (
        "Hello! We're here to help. If you need immediate assistance, "
        "please tap the button below to call our support team."
    )

    result = message_service.send_support_message(
        conversation_id, 
        support_message, 
        support_phone
    )

    print(result)

if __name__ == '__main__':
    main()

import os
import logging
import docker
import socket
from docker.utils import kwargs_from_env
from docker.errors import APIError, DockerException

class DockerConfig:
    _ENABLED = False
    _DOCKER_POOL = None
    _DOCKER_COMPUTE = None
    _DOCKER_DELEGATE = None

    @staticmethod
    def docker_enabled():
        """
        Determine whether Docker integration is enabled
        """
        if DockerConfig._ENABLED:
            return True

        try:
            docker.from_env()
            DockerConfig._ENABLED = True
        except Exception:
            logging.warning("Docker client initialization failed")

        return DockerConfig._ENABLED

    @staticmethod
    def docker_client(version='auto', timeout=60):
        """
        Create and configure Docker client with flexible options
        """
        try:
            client_kwargs = {
                'version': version,
                'timeout': timeout
            }

            # Environment-based configuration
            env_kwargs = kwargs_from_env(assert_hostname=False)
            client_kwargs.update(env_kwargs)

            # Boot2Docker compatibility
            if 'DOCKER_HOST' not in os.environ:
                try:
                    default_socket = 'unix://var/run/docker.sock'
                    client_kwargs['base_url'] = default_socket
                except Exception:
                    pass

            return docker.from_env(**client_kwargs)
        except Exception as e:
            logging.error(f"Docker client creation failed: {e}")
            return None

    @staticmethod
    def docker_host_ip():
        """
        Retrieve Docker host IP address with multiple fallback strategies
        """
        try:
            # Priority: Environment variable
            if 'DOCKER_HOST_IP' in os.environ:
                return os.environ['DOCKER_HOST_IP']

            # Attempt socket-based detection
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
                s.connect(('8.8.8.8', 80))
                host_ip = s.getsockname()[0]
                return host_ip
        except Exception:
            return '127.0.0.1'

    @staticmethod
    def pull_image(image_name, tag='latest'):
        """
        Pull Docker image with robust error handling
        """
        try:
            client = DockerConfig.docker_client()
            if not client:
                logging.warning(f"Cannot pull image {image_name}: Docker client unavailable")
                return None

            full_image = f"{image_name}:{tag}"
            logging.info(f"Pulling Docker image: {full_image}")

            return client.images.pull(full_image)
        except APIError as api_err:
            logging.error(f"Docker API error during image pull: {api_err}")
        except DockerException as docker_err:
            logging.error(f"Docker exception during image pull: {docker_err}")
        return None

    @staticmethod
    def get_compute(driver='docker'):
        """
        Configure and retrieve compute driver
        """
        if DockerConfig._DOCKER_COMPUTE:
            return DockerConfig._DOCKER_COMPUTE

        try:
            from cattle import compute
            DockerConfig._DOCKER_COMPUTE = compute.Driver(driver)
            return DockerConfig._DOCKER_COMPUTE
        except ImportError:
            logging.warning("Cattle compute module not available")
            return None

    @staticmethod
    def register_docker_driver():
        """
        Register Docker-specific drivers and handlers
        """
        try:
            compute_driver = DockerConfig.get_compute()
            if compute_driver:
                compute_driver.register()
                logging.info("Docker compute driver registered successfully")
        except Exception as e:
            logging.error(f"Docker driver registration failed: {e}")

    @staticmethod
    def configure_docker_integration(config=None):
        """
        Comprehensive Docker integration configuration
        """
        config = config or {}
        docker_enabled = config.get('docker_enabled', True)

        if not docker_enabled:
            logging.info("Docker integration disabled")
            return False

        # Validate Docker availability
        if not DockerConfig.docker_enabled():
            logging.warning("Docker is not available")
            return False

        # Initialize Docker client and resources
        try:
            client = DockerConfig.docker_client()
            if not client:
                return False

            # Optional: Pool initialization
            DockerConfig._DOCKER_POOL = client

            # Register drivers
            DockerConfig.register_docker_driver()

