RESOURCES_PATH = '/share-servers'
RESOURCE_PATH = '/share-servers/%s'
RESOURCES_NAME = 'share_servers'
RESOURCE_NAME = 'share_server'

class ShareServer(base.Resource):
    """
    Represents a share server resource in OpenStack Manila.
    """
    def __repr__(self):
        return f'<ShareServer: {self.id}>'

    def delete(self):
        """
        Delete the current share server instance.
        """
        return self.manager.delete(self)

    def details(self):
        """
        Retrieve detailed information about the share server.
        """
        return self.manager.get(self.id)

    def __getattr__(self, key):
        """
        Dynamic attribute access for share server properties.
        """
        if key in self._info:
            return self._info[key]
        raise AttributeError(f"ShareServer object has no attribute '{key}'")


class ShareServerManager(base.Manager):
    """
    Manage share server resources with CRUD operations.
    """
    resource_class = ShareServer

    def _encode_query_params(self, search_opts):
        """
        Encode query parameters for list operations.
        """
        if not search_opts:
            return ''

        try:
            # Python 3
            from urllib.parse import urlencode
        except ImportError:
            # Python 2 fallback
            from urllib import urlencode

        return '?' + urlencode(search_opts)

    def list(self, detailed=False, search_opts=None):
        """
        List share servers with optional filtering.

        :param detailed: Include detailed server information
        :param search_opts: Dictionary of search/filter parameters
        :return: List of share server resources
        """
        search_opts = search_opts or {}
        query_string = self._encode_query_params(search_opts)
        path = f'{RESOURCES_PATH}/detail' if detailed else RESOURCES_PATH

        return self._list(path + query_string, RESOURCES_NAME)

    def get(self, share_server):
        """
        Retrieve details for a specific share server.

        :param share_server: Share server ID or object
        :return: Detailed share server resource
        """
        if hasattr(share_server, 'id'):
            share_server_id = share_server.id
        else:
            share_server_id = share_server

        return self._get(RESOURCE_PATH % share_server_id, RESOURCE_NAME)

    def delete(self, share_server):
        """
        Delete a specific share server.

        :param share_server: Share server ID or object
        """
        if hasattr(share_server, 'id'):
            share_server_id = share_server.id
        else:
            share_server_id = share_server

        return self._delete(RESOURCE_PATH % share_server_id)

    def backend_details(self, share_server):
        """
        Retrieve backend-specific details for a share server.

        :param share_server: Share server ID or object
        :return: Backend details dictionary
        """
        if hasattr(share_server, 'id'):
            share_server_id = share_server.id
        else:
            share_server_id = share_server

        path = f'{RESOURCE_PATH}/backend_details' % share_server_id
        try:
            response = self.api.client.get(path)
            return response.get('backend_details', {})
        except Exception as e:
            raise exceptions.APIException(f"Error retrieving backend details: {e}")


class ShareServerClient:
    """
    Client for interacting with share server resources.
    """
    def __init__(self, client):
        self.client = client
        self.share_servers = ShareServerManager(client)

import ctypes
import numpy as np
from OpenGL.GL import *
from OpenGL.GLU import *
from OpenGL.GLUT import *
from OpenGL.platform import *
from OpenGL.constants import *

class FragmentProgramManager:
    def __init__(self):
        self._program_id = None
        self._vector_registers = {}
        self._instruction_sequence = []
        self._max_fragment_registers = 32

    def create_program(self):
        self._program_id = glGenProgramsARB(1)
        glBindProgramARB(GL_FRAGMENT_PROGRAM_ARB, self._program_id)
        return self._program_id

    def define_vector_register(self, register_name, initial_values):
        if len(self._vector_registers) >= self._max_fragment_registers:
            raise ValueError("Maximum fragment registers exceeded")

        vector = np.array(initial_values, dtype=np.float32)
        if vector.shape != (4,):
            raise ValueError("Vector must be 4-component")

        self._vector_registers[register_name] = vector

    def add_instruction(self, instruction_type, dest_register, src_registers, operation):
        instruction = {
            'type': instruction_type,
            'destination': dest_register,
            'sources': src_registers,
            'operation': operation
        }
        self._instruction_sequence.append(instruction)

    def compile_program(self):
        program_source = self._generate_program_source()
        glProgramStringARB(
            GL_FRAGMENT_PROGRAM_ARB, 
            GL_PROGRAM_FORMAT_ASCII_ARB, 
            len(program_source), 
            program_source
        )
        self._validate_program()

    def _generate_program_source(self):
        program_lines = [
            "!!ARBfp1.0",
            "PARAM environment = { 0, 0, 0, 1 };"
        ]

        # Define temporary registers
        for name, vector in self._vector_registers.items():
            program_lines.append(f"TEMP {name};")

        # Generate instruction sequence
        for instruction in self._instruction_sequence:
            if instruction['type'] == 'move':
                program_lines.append(f"MOV {instruction['destination']}, {instruction['sources'][0]};")
            elif instruction['type'] == 'add':
                program_lines.append(f"ADD {instruction['destination']}, {instruction['sources'][0]}, {instruction['sources'][1]};")
            elif instruction['type'] == 'multiply':
                program_lines.append(f"MUL {instruction['destination']}, {instruction['sources'][0]}, {instruction['sources'][1]};")

        program_lines.append("END")
        return '\n'.join(program_lines)

    def _validate_program(self):
        program_error = glGetError()
        if program_error != GL_NO_ERROR:
            error_position = glGetIntegerv(GL_PROGRAM_ERROR_POSITION_ARB)
            error_string = glGetString(GL_PROGRAM_ERROR_STRING_ARB)
            raise RuntimeError(f"Fragment program compilation error at position {error_position}: {error_string}")

    def apply_program(self):
        glEnable(GL_FRAGMENT_PROGRAM_ARB)
        glBindProgramARB(GL_FRAGMENT_PROGRAM_ARB, self._program_id)

    def disable_program(self):
        glDisable(GL_FRAGMENT_PROGRAM_ARB)

import os
import sys
import yaml
import re
import hashlib
import uuid

class IgnoreRule:
    def __init__(self, rule_type, pattern, reason=None):
        self.id = str(uuid.uuid4())
        self.type = rule_type
        self.pattern = pattern
        self.reason = reason or "No reason provided"
        self.compiled_pattern = self._compile_pattern()

    def _compile_pattern(self):
        try:
            if self.type == 'regex':
                return re.compile(self.pattern, re.IGNORECASE)
            return None
        except re.error:
            return None

    def match(self, message):
        if self.type == 'host':
            return self._match_host(message)
        elif self.type == 'nick':
            return self._match_nick(message)
        elif self.type == 'regex':
            return self._match_regex(message)
        return False

    def _match_host(self, message):
        return fnmatch.fnmatch(message.get('host', ''), self.pattern)

    def _match_nick(self, message):
        return message.get('nick', '').lower() == self.pattern.lower()

    def _match_regex(self, message):
        if self.compiled_pattern:
            return self.compiled_pattern.search(message.get('text', ''))
        return False

class IgnoreRuleSet:
    def __init__(self, config_path=None):
        self.rules = {}
        self.config_path = config_path or os.path.expanduser('~/.irc_ignore_rules.yml')
        self.load()

    def load(self):
        try:
            with open(self.config_path, 'r') as f:
                config = yaml.safe_load(f) or {}
                for rule_data in config.get('rules', []):
                    rule = IgnoreRule(
                        rule_type=rule_data.get('type'),
                        pattern=rule_data.get('pattern'),
                        reason=rule_data.get('reason')
                    )
                    self.rules[rule.id] = rule
        except FileNotFoundError:
            self._create_default_config()
        except yaml.YAMLError:
            print(f"Invalid YAML configuration in {self.config_path}")

    def _create_default_config(self):
        default_config = {'rules': []}
        with open(self.config_path, 'w') as f:
            yaml.dump(default_config, f)

    def install_rule(self, rule_type, pattern, reason=None):
        rule = IgnoreRule(rule_type, pattern, reason)
        self.rules[rule.id] = rule
        self._save_config()
        return rule.id

    def uninstall_rule(self, rule_id):
        if rule_id in self.rules:
            del self.rules[rule_id]
            self._save_config()
            return True
        return False

    def _save_config(self):
        config = {
            'rules': [
                {
                    'id': rule.id,
                    'type': rule.type,
                    'pattern': rule.pattern,
                    'reason': rule.reason
                } for rule in self.rules.values()
            ]
        }
        with open(self.config_path, 'w') as f:
            yaml.dump(config, f)

    def test_message(self, message):
        for rule in self.rules.values():
            if rule.match(message):
                return rule
        return None

def weechat_filter_cb(data, buffer, date, tags, display, highlight, prefix, message):
    ruleset = IgnoreRuleSet()
    ignore_rule = ruleset.test_message({
        'nick': prefix,
        'text': message,
        'tags': tags
    })

    if ignore_rule:
        return weechat.WEECHAT_RC_OK_EAT

    return weechat.WEECHAT_RC_OK

def main():
    ruleset = IgnoreRuleSet()
    # Optional: command-line argument processing for dynamic rule management
    if len(sys.argv) > 1:
        action = sys.argv[1]
        if action == 'install':
            ruleset.install_rule(sys.argv[2], sys.argv[3])
        elif action == 'uninstall':
            ruleset.uninstall_rule(sys.argv[2])

if __name__ == "__main__":
    main()

import os
import unittest
import tempfile
from tigerlily.utility.archive import Archive
from tigerlily.sequences import FastaReader

class ArchiveTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.test_dir = os.path.join(os.path.dirname(__file__), 'test_archives')
        cls.targz = os.path.join(cls.test_dir, 'test_archive.tar.gz')
        cls.tarbz2 = os.path.join(cls.test_dir, 'test_archive.tar.bz2')
        cls.tar = os.path.join(cls.test_dir, 'test_archive.tar')
        cls.zip_file = os.path.join(cls.test_dir, 'test_archive.zip')

    def setUp(self):
        self.temp_dir = tempfile.mkdtemp()

    def tearDown(self):
        for root, dirs, files in os.walk(self.temp_dir, topdown=False):
            for name in files:
                os.remove(os.path.join(root, name))
            for name in dirs:
                os.rmdir(os.path.join(root, name))
        os.rmdir(self.temp_dir)

    def _handle_arch(self, arch_path, expected_files=None):
        archive = Archive(arch_path)
        archive.extract(self.temp_dir)

        extracted_files = [
            f for f in os.listdir(self.temp_dir)
            if os.path.isfile(os.path.join(self.temp_dir, f))
        ]

        if expected_files:
            self.assertEqual(
                set(extracted_files),
                set(expected_files),
                f"File mismatch for {arch_path}"
            )

        fasta_files = [
            f for f in extracted_files
            if f.lower().endswith('.fasta') or f.lower().endswith('.fa')
        ]

        for fasta_file in fasta_files:
            full_path = os.path.join(self.temp_dir, fasta_file)
            with open(full_path, 'r') as f:
                reader = FastaReader(f)
                sequences = list(reader)
                self.assertTrue(
                    sequences,
                    f"No sequences found in {fasta_file}"
                )

        return extracted_files

    def test_targz(self):
        expected_files = ['sample1.fasta', 'sample2.fasta']
        files = self._handle_arch(self.targz, expected_files)
        self.assertEqual(len(files), 2)

    def test_tarbz2(self):
        expected_files = ['sample3.fasta', 'sample4.fasta']
        files = self._handle_arch(self.tarbz2, expected_files)
        self.assertEqual(len(files), 2)

    def test_tar(self):
        expected_files = ['sample5.fasta']
        files = self._handle_arch(self.tar, expected_files)
        self.assertEqual(len(files), 1)

    def test_zip(self):
        expected_files = ['sample6.fasta', 'sample7.fasta']
        files = self._handle_arch(self.zip_file, expected_files)
        self.assertEqual(len(files), 2)

    def test_nonexistent_archive(self):
        with self.assertRaises(FileNotFoundError):
            Archive('/path/to/nonexistent/archive.tar.gz')

    def test_unsupported_format(self):
        unsupported_file = os.path.join(self.test_dir, 'unsupported.rar')
        with self.assertRaises(ValueError):
            Archive(unsupported_file)

if __name__ == '__main__':
    unittest.main()

import unittest
import DocutilsTestSupport

class InlineMarkupTests(DocutilsTestSupport.PEPParserTestSuite):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.test_cases = {}

    def setUp(self):
        self.test_cases = {
            'simple_reference': [
                ('PEP 8', '<reference>PEP 8</reference>'),
                ('RFC 2822', '<reference>RFC 2822</reference>'),
                ('PEP 257', '<reference>PEP 257</reference>')
            ],
            'complex_reference': [
                ('See `PEP 8 <https://peps.python.org/pep-0008/>`_', 
                 '<reference>See PEP 8</reference>'),
                ('Refer to "RFC 3986"', '<reference>RFC 3986</reference>')
            ],
            'inline_markup': [
                ('*emphasis*', '<emphasis>emphasis</emphasis>'),
                ('**strong**', '<strong>strong</strong>'),
                ('``literal``', '<literal>literal</literal>'),
                ('_underline_', '<underline>underline</underline>')
            ],
            'mixed_references': [
                ('Inline *PEP 8* reference', 
                 '<paragraph>Inline <emphasis>PEP 8</emphasis> reference</paragraph>'),
                ('Complex ``RFC 2822`` parsing', 
                 '<paragraph>Complex <literal>RFC 2822</literal> parsing</paragraph>')
            ],
            'substitution_references': [
                ('|python_logo|', '<substitution_reference>python_logo</substitution_reference>'),
                ('Embedded |trademark| symbol', 
                 '<paragraph>Embedded <substitution_reference>trademark</substitution_reference> symbol')
            ],
            'footnote_references': [
                ('[1]_', '<footnote_reference>1</footnote_reference>'),
                ('Footnote [#note]_', 
                 '<paragraph>Footnote <footnote_reference>note</footnote_reference></paragraph>')
            ],
            'target_references': [
                ('.. _Python: https://www.python.org', 
                 '<target>Python</target>'),
                ('External link `Python Homepage <https://www.python.org>`__', 
                 '<reference>Python Homepage</reference>')
            ]
        }

    def validate_parsing(self, test_category):
        for input_text, expected_output in self.test_cases.get(test_category, []):
            result = self.parse(input_text)
            self.assertIn(expected_output, result)

    def test_simple_references(self):
        self.validate_parsing('simple_reference')

    def test_complex_references(self):
        self.validate_parsing('complex_reference')

    def test_inline_markup(self):
        self.validate_parsing('inline_markup')

    def test_mixed_references(self):
        self.validate_parsing('mixed_references')

    def test_substitution_references(self):
        self.validate_parsing('substitution_references')

    def test_footnote_references(self):
        self.validate_parsing('footnote_references')

    def test_target_references(self):
        self.validate_parsing('target_references')

    def test_cross_line_references(self):
        multi_line_text = '''
        This is a multi-line
        reference to *PEP 8* and
        ``RFC 2822``.
        '''
        result = self.parse(multi_line_text)
        self.assertIn('<emphasis>PEP 8</emphasis>', result)
        self.assertIn('<literal>RFC 2822</literal>', result)

    def test_edge_cases(self):
        edge_cases = [
            ('', ''),  # Empty input
            (' ', ''),  # Whitespace input
            ('No references', 'No references'),  # No markup
            ('*Unclosed emphasis', '*Unclosed emphasis')  # Incomplete markup
        ]
        for input_text, expected_output in edge_cases:
            result = self.parse(input_text)
            self.assertIn(expected_output, result)

def suite():
    suite = unittest.TestSuite()
    suite.addTest(unittest.makeSuite(InlineMarkupTests))
    return suite

