import zmq
import serial
import time
import logging
from zmq.eventloop.ioloop import IOLoop
from zmq.eventloop.zmqstream import ZMQStream

SERVICE_NAME = "motor_control_service"
SERVICE_PORT = 5555
COMMAND_GRACE_TIME = 2.0  # seconds
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200

class MotorServer:
    def __init__(self):
        self.context = zmq.Context()
        self.socket = self.context.socket(zmq.REP)
        self.socket.bind(f"tcp://*:{SERVICE_PORT}")
        self.stream = ZMQStream(self.socket)
        self.stream.on_recv(self.message_received)

        try:
            self.serial_port = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                timeout=0.1
            )
        except serial.SerialException as e:
            logging.error(f"Serial port error: {e}")
            raise

        self.input_buffer = ""
        self.last_command_time = time.time()
        self.current_speeds = {'left': 0, 'right': 0}

        self.ioloop = IOLoop.current()
        self.ioloop.add_timeout(
            self.ioloop.time() + COMMAND_GRACE_TIME,
            self.check_data_received
        )

        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def message_received(self, message):
        try:
            msg = message[0].decode('utf-8')
            speeds = self._parse_speeds(msg)
            self._setspeeds(speeds)
            self.socket.send_string("Speed set successfully")
            self.last_command_time = time.time()
        except Exception as e:
            self.socket.send_string(f"Error: {str(e)}")
            self.logger.error(f"Message processing error: {e}")

    def _parse_speeds(self, msg):
        try:
            left, right = map(int, msg.split(','))
            return {'left': left, 'right': right}
        except ValueError:
            raise ValueError("Invalid speed format")

    def _setspeeds(self, speeds):
        left_speed = max(min(speeds['left'], 100), -100)
        right_speed = max(min(speeds['right'], 100), -100)

        command = f"M:{left_speed},{right_speed}\n"
        try:
            self.serial_port.write(command.encode('utf-8'))
            self.current_speeds = speeds
            self.logger.info(f"Motor speeds set: {speeds}")
        except serial.SerialException as e:
            self.logger.error(f"Serial write error: {e}")

    def check_data_received(self):
        elapsed_time = time.time() - self.last_command_time
        if elapsed_time >= COMMAND_GRACE_TIME:
            self._setspeeds({'left': 0, 'right': 0})
            self.logger.warning("No command received. Stopping motors.")

        self.ioloop.add_timeout(
            self.ioloop.time() + COMMAND_GRACE_TIME,
            self.check_data_received
        )

    def handle_serial_event(self):
        try:
            if self.serial_port.in_waiting:
                data = self.serial_port.read(self.serial_port.in_waiting)
                self.input_buffer += data.decode('utf-8')
        except serial.SerialException as e:
            self.logger.error(f"Serial read error: {e}")

    def cleanup(self):
        self._setspeeds({'left': 0, 'right': 0})
        self.serial_port.close()
        self.context.term()
        self.logger.info("Motor server shutdown complete")

def main():
    try:
        motor_server = MotorServer()
        IOLoop.current().start()
    except KeyboardInterrupt:
        motor_server.cleanup()
    except Exception as e:
        logging.error(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()
